+}
+
+function spawnDust(pos){
+ if(dust){scene.remove(dust); }
+ const N=260, arr=new Float32Array(N*3); dustVel=[];
+ const r=mulberry32(999);
+ for(let i=0;i<N;i++){ arr[i*3]=pos.x+(r()-0.5)*1.2; arr[i*3+1]=0.3+r()*1.4; arr[i*3+2]=(r()-0.5)*2.2; dustVel.push([(r()-0.2)*4,r()*3.5,(r()-0.5)*5]); }
+ const g=new THREE.BufferGeometry(); g.setAttribute('position',new THREE.BufferAttribute(arr,3));
