+ const M=60, a2=new Float32Array(M*3); for(let i=0;i<M;i++){a2[i*3]=pos.x+0.8;a2[i*3+1]=0.6;a2[i*3+2]=(r()-0.5)*1.5;}
+ const g2=new THREE.BufferGeometry(); g2.setAttribute('position',new THREE.BufferAttribute(a2,3));
