+
+function clearWorld(){
+ meshes.forEach(m=>{scene.remove(m); if(m.geometry&&m.geometry.dispose)m.geometry.dispose();});
+ meshes=[]; bodies=[]; joints=[]; bricks=[]; dust=null; sparks=null;
+ if(world){ world.bodies.slice().forEach(b=>world.removeBody(b)); }
+}
+function reset(){
+ clearWorld();
+ S={...S}; // keep current settings
+ wallX=S.trackLength/2-6; trackLen=S.trackLength;
