+ world.broadphase=new CANNON.SAPBroadphase(world); world.allowSleep=true;
+ world.solver.iterations=12; world.defaultContactMaterial.friction=S.groundFriction;
+ matGround=new CANNON.Material('ground'); matBrick=new CANNON.Material('brick'); matCar=new CANNON.Material('car');
+ world.addContactMaterial(new CANNON.ContactMaterial(matGround,matBrick,{friction:S.groundFriction,restitution:0.05}));
+ world.addContactMaterial(new CANNON.ContactMaterial(matGround,matCar,{friction:S.groundFriction,restitution:0.05}));
+ world.addContactMaterial(new CANNON.ContactMaterial(matBrick,matBrick,{friction:S.brickFriction,restitution:S.brickRestitution}));
+ world.addContactMaterial(new CANNON.ContactMaterial(matBrick,matCar,{friction:S.brickFriction,restitution:S.brickRestitution}));
+ world.addContactMaterial(new CANNON.ContactMaterial(matCar,matCar,{friction:0.4,restitution:0.08}));
