+}
+
+// settings UI
+const FIELDS=[['speed','Impact speed (m/s)'],['carMass','Car mass (kg)'],['carLength','Car length (m)'],['carWidth','Car width (m)'],['carHeight','Car height (m)'],['wallCols','Wall columns'],['wallRows','Wall rows'],['wallDepth','Wall depth'],['brickMass','Brick mass (kg)'],['brickW','Brick width (m)'],['brickH','Brick height (m)'],['brickD','Brick depth (m)'],['gravity','Gravity (m/s²)'],['brickFriction','Brick friction'],['brickRestitution','Brick restitution'],['groundFriction','Ground friction'],['trackLength','Track length (m)']];
+const fieldsEl=document.getElementById('fields');
+FIELDS.forEach(([k,label])=>{ const l=document.createElement('label'); l.textContent=label; const inp=document.createElement('input'); inp.type='number'; inp.step='any'; inp.id='f_'+k; inp.value=S[k]; fieldsEl.appendChild(l); fieldsEl.appendChild(inp); });
+function readSettings(){ FIELDS.forEach(([k])=>{ const v=parseFloat(document.getElementById('f_'+k).value); if(Number.isFinite(v)&&v>0) S[k]=v; }); S.wallCols=Math.max(1,Math.round(S.wallCols)); S.wallRows=Math.max(1,Math.round(S.wallRows)); S.wallDepth=Math.max(1,Math.round(S.wallDepth)); }
+function writeSettings(){ FIELDS.forEach(([k])=>document.getElementById('f_'+k).value=S[k]); }
+
+document.getElementById('applyBtn').onclick=()=>{readSettings(); reset();};
