+document.getElementById('replayBtn').onclick=()=>{readSettings(); reset();};
+document.getElementById('settingsBtn').onclick=()=>document.getElementById('panel').classList.toggle('open');
+const playBtn=document.getElementById('playBtn');
+function setPaused(p){ paused=p; playBtn.textContent=paused?'▶ Play':'⏸ Pause'; document.getElementById('status').textContent=paused?'Paused':(impacted?'Wreck settling':'Running'); }
+playBtn.onclick=()=>setPaused(!paused);
